function deg(r){return r*180/Math.PI;}
function rad(d){return d*Math.PI/180;}
function lawCosSide(a,b,C){return Math.sqrt(a*a+b*b-2*a*b*Math.cos(C));}
function lawCosAngle(a,b,c){return Math.acos((a*a+b*b-c*c)/(2*a*b));}
function solveTriangle(s){ // s: {a,b,c,A,B,C} 角度为度，未知用 undefined
  var o={};for(var k in s)o[k]=s[k];
  function set(name,v){o[name]=v;}
  if(o.a!=null&&o.b!=null&&o.c!=null){
    set('A',deg(lawCosAngle(o.b,o.c,o.a)));set('B',deg(lawCosAngle(o.a,o.c,o.b)));set('C',deg(lawCosAngle(o.a,o.b,o.c)));
  } else if(o.a!=null&&o.b!=null&&o.C!=null){
    var c=lawCosSide(o.a,o.b,rad(o.C));set('c',c);
    set('A',deg(lawCosAngle(o.b,c,o.a)));set('B',deg(lawCosAngle(o.a,c,o.b)));
  } else if(o.A!=null&&o.B!=null&&o.a!=null){
    var C=180-o.A-o.B;set('C',C);
    var b=o.a*Math.sin(rad(o.B))/Math.sin(rad(o.A));var c=o.a*Math.sin(rad(C))/Math.sin(rad(o.A));
    set('b',b);set('c',c);
  } else throw new Error('无法求解：请提供 SSS / SAS / ASA(AAS) 组合');
  var p=(o.a+o.b+o.c)/2;set('area',Math.sqrt(Math.max(0,p*(p-o.a)*(p-o.b)*(p-o.c))));
  return o;
}
var EXPORTS={solveTriangle:solveTriangle,lawCosSide:lawCosSide,lawCosAngle:lawCosAngle};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GeometryForgePure = EXPORTS; }
